SELECT DISTINCT s.id, s.name, s.category_id, s.brand_id, s.description, s.unit, s.keywords, s.sales, s.status, s.main_image, s.images, s.created_at, s.updated_at FROM spu s LEFT JOIN categories c ON s.category_id = c.id LEFT JOIN brands b ON s.brand_id = b.id WHERE 1=1
AND s.category_id IN
#{categoryId}
AND ( s.name LIKE CONCAT('%', #{keyword}, '%') OR c.name LIKE CONCAT('%', #{keyword}, '%') OR b.name LIKE CONCAT('%', #{keyword}, '%') )
AND s.brand_id = #{brandId}
ORDER BY s.created_at DESC LIMIT #{offset}, #{limit}

SELECT COUNT(DISTINCT s.id) FROM spu s LEFT JOIN categories c ON s.category_id = c.id LEFT JOIN brands b ON s.brand_id = b.id WHERE 1=1
AND s.category_id IN
#{categoryId}
AND ( s.name LIKE CONCAT('%', #{keyword}, '%') OR c.name LIKE CONCAT('%', #{keyword}, '%') OR b.name LIKE CONCAT('%', #{keyword}, '%') )
AND s.brand_id = #{brandId}
